CREATE OR REPLACE FUNCTION private.guard_review_comment_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 -- The comment is part of an immutable review: no author edit, no author delete, for every role. Exactly two paths exist, both service-owned and both narrower than the table.
 if auth.role()='service_role' then
  -- 1. The account-closure erasure certificate (one locked row, one fixed DELETE patch, inside the service-owned SQL transaction): the author's own text goes, the review row stays.
  if tg_op='DELETE' and private.closure_redaction_allowed_v5(tg_relid,tg_op,to_jsonb(old),null) then return old; end if;
  -- 2. The audited moderation function: ONLY the two hide columns, ONLY while its transaction-local marker is on, and nothing else of the row may change.
  if tg_op='UPDATE' and current_setting('uskoci.review_comment_moderation',true) is not distinct from 'on'
   and (to_jsonb(new)-array['hidden_at','hidden_reason_code']) is not distinct from (to_jsonb(old)-array['hidden_at','hidden_reason_code']) then
   return new;
  end if;
 end if;
 raise exception 'REVIEW_COMMENT_IMMUTABLE' using errcode='42501';
end;
$function$

CREATE OR REPLACE FUNCTION private.review_comment_input_v1(p_comment jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare v text; n text;
begin
 -- Absent: SQL NULL, JSON null, or a string with nothing but white space. Nothing is stored for an absent comment and a later comment can never be added (the review is immutable).
 if p_comment is null or jsonb_typeof(p_comment)='null' then return null; end if;
 if jsonb_typeof(p_comment)<>'string' then raise exception 'REVIEW_COMMENT_INVALID' using errcode='22023'; end if;
 if octet_length(p_comment::text)>8192 then raise exception 'REVIEW_COMMENT_TOO_LONG' using errcode='22023'; end if;
 v:=p_comment#>>'{}';
 -- "No comment": white space (an EXPLICIT class: ASCII white space U+0009..U+000D and U+0020, U+0085 and the Unicode separators; never the locale dependent POSIX class, so U+001C..U+001F are not blank and a lone one is INVALID in every
 -- locale), characters that render as nothing but are tolerated inside a sentence (soft hyphen, combining grapheme joiner, braille blank), the two joiners and ALL sixteen variation selectors ONLY. Every class below is built from chr() pieces:
 -- no escape text, no invisible character in this source. The forbidden class below is every default-ignorable code point of Unicode 17.0 except those allowed-inside groups, plus the controls (see README_D12_CANDIDATE.md, Text rules).
 if btrim(v,E' \n')='' or v ~ ('^[' || chr(9) || '-' || chr(13) || chr(32) || chr(133) || chr(160) || chr(173) || chr(847) || chr(5760) || chr(8192) || '-' || chr(8202) || chr(8204) || '-' || chr(8205) || chr(8232) || '-' || chr(8233) || chr(8239) || chr(8287) || chr(10240) || chr(12288) || chr(65024) || '-' || chr(65039) || ']*$') then return null; end if;
 -- The length is counted in code points of the text as sent; the octet cap is defence in depth (500 code points are at most 2000 octets, so it can never fire first). The server REJECTS, it never normalises (the client compares the echoed text).
 if char_length(v)>500 or octet_length(v)>2000 then raise exception 'REVIEW_COMMENT_TOO_LONG' using errcode='22023'; end if;
 if v<>btrim(v,E' \n') or v ~ ('[' || chr(1) || '-' || chr(9) || chr(11) || '-' || chr(31) || chr(127) || '-' || chr(159) || chr(1564) || chr(4447) || '-' || chr(4448) || chr(6068) || '-' || chr(6069) || chr(6155) || '-' || chr(6159) || chr(8203) || chr(8206) || '-' || chr(8207) || chr(8232) || '-' || chr(8238) || chr(8288) || '-' || chr(8303) || chr(12644) || chr(65279) || chr(65440) || chr(65520) || '-' || chr(65531) || chr(78896) || '-' || chr(78911) || chr(113824) || '-' || chr(113827) || chr(119155) || '-' || chr(119162) || chr(917504) || '-' || chr(921599) || ']') then raise exception 'REVIEW_COMMENT_INVALID' using errcode='22023'; end if;
 -- Deterministic contact floor (no AI, no provider): e-mail, link, @handle and a phone number that starts with 0, 00, + or 381 (8 to 13 digits, not a date shape) are refused with ONE plain code (the live PKG-029c floor). It runs on the text as sent
 -- AND on an NFKC-normalised copy without invisible characters and with Arabic-Indic and Persian digits mapped to ASCII, so full-width digits or '@', a soft hyphen or a zero-width joiner inside a number do not hide it; the STORED text is the original.
 -- It is a screen against careless contact details, NOT privacy protection: a number without its leading 0 or 381, 7-digit runs, digits split by letters or by combining marks, digits of other numeral systems (for example Devanagari),
 -- spelled-out numbers, bare domains, short links and handles without @ pass.
 n:=translate(regexp_replace(normalize(v,NFKC),('[' || chr(173) || chr(847) || chr(8204) || '-' || chr(8205) || chr(10240) || chr(65024) || '-' || chr(65039) || ']'),'','g'),chr(1632) || chr(1633) || chr(1634) || chr(1635) || chr(1636) || chr(1637) || chr(1638) || chr(1639) || chr(1640) || chr(1641) || chr(1776) || chr(1777) || chr(1778) || chr(1779) || chr(1780) || chr(1781) || chr(1782) || chr(1783) || chr(1784) || chr(1785),'01234567890123456789');
 if private.ru4b_public_floor_reason(v) is not null or private.ru4b_public_floor_reason(n) is not null then raise exception 'REVIEW_COMMENT_CONTACT_NOT_PUBLIC' using errcode='22023'; end if;
 return v;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_confirm_completion(p_agreement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  uid uuid:=auth.uid();
  v_need_id uuid;
  n public.needs%rowtype;
  a public.agreements%rowtype;
  x public.agreement_execution%rowtype;
  v_completed_at timestamptz;
  need_completed boolean;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;

  select ag.need_id into v_need_id from public.agreements ag where ag.id=p_agreement_id;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;

  select * into n from public.needs nd where nd.id=v_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;

  select * into a from public.agreements ag where ag.id=p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;
  if a.need_id<>n.id then raise exception 'AGREEMENT_NEED_MISMATCH' using errcode='P0001'; end if;
  if a.requester_account_id<>uid then
    raise exception 'ONLY_REQUESTER_CAN_CONFIRM_COMPLETION' using errcode='42501';
  end if;

  select * into x from public.agreement_execution ex where ex.agreement_id=a.id for update;
  if not found then raise exception 'EXECUTION_NOT_FOUND' using errcode='P0002'; end if;
  if x.agreement_version<>a.current_version then
    raise exception 'EXECUTION_VERSION_MISMATCH' using errcode='P0001';
  end if;

  if a.status='COMPLETED' and x.state='COMPLETED' then
    return jsonb_build_object(
      'agreementId',a.id,'state','COMPLETED',
      'completedAt',x.completed_at,
      'idempotentReplay',true,'authoritative',true
    );
  end if;

  if a.status='CANCELLED' or x.state='CANCELLED' then
    raise exception 'AGREEMENT_CANCELLED' using errcode='P0001';
  end if;

  if a.status<>'CONFIRMED'
     or x.state not in ('CONFIRMED','AWAITING_REQUESTER') then
    raise exception 'COMPLETION_NOT_CONFIRMABLE'
      using errcode='P0001',
            detail=jsonb_build_object('agreementStatus',a.status,'executionState',x.state)::text;
  end if;

  if exists(select 1 from public.agreement_change_proposals where agreement_id=a.id and status='PENDING') then
    raise exception 'AGREEMENT_CHANGE_PENDING' using errcode='P0001';
  end if;

  v_completed_at:=statement_timestamp();

  update public.agreement_execution ex
     set state='COMPLETED',
         completed_at=coalesce(ex.completed_at,v_completed_at),
         requester_deadline_at=null,
         updated_at=statement_timestamp()
   where ex.agreement_id=a.id
  returning ex.* into x;

  update public.agreements ag
     set status='COMPLETED',updated_at=statement_timestamp()
   where ag.id=a.id;

  need_completed:=private.sync_need_completion(n.id);

  perform private.emit_event(
    a.worker_account_id,'WORKER','EXECUTION_STATE_CHANGED',
    'AGREEMENT',a.id,a.current_version,
    'Dogovor je završen',
    'Naručilac je potvrdio završetak.',
    'completed:worker:'||a.id::text||':'||a.current_version::text,
    'NORMAL',
    jsonb_build_object('completedAt',x.completed_at),
    null
  );

  return jsonb_build_object(
    'agreementId',a.id,
    'state','COMPLETED',
    'completedAt',x.completed_at,
    'needCompleted',need_completed,
    'problemWasPreviouslyReported',x.problem_opened_at is not null,
    'idempotentReplay',false,
    'authoritative',true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_account_reputation(p_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_account_id is null or not exists(select 1 from public.app_accounts where id=p_account_id)
 or private.closure_account_restricted(auth.uid()) or private.closure_account_restricted(p_account_id)
 or (auth.uid()<>p_account_id and private.safety_pair_blocked(auth.uid(),p_account_id)) then
  raise exception 'REPUTATION_NOT_AVAILABLE' using errcode='42501';
 end if;
 return private.account_reputation(p_account_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_my_agreement_review(p_agreement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); a public.agreements; r private.agreement_reviews; own_review jsonb;
begin
 if u is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into a from public.agreements where id=p_agreement_id and u in(requester_account_id,worker_account_id);
 if not found then raise exception 'REVIEW_NOT_ALLOWED' using errcode='42501'; end if;
 select * into r from private.agreement_reviews where agreement_id=a.id and reviewer_account_id=u;
 own_review:=case when found then private.review_receipt(r,false) else null end;
 return jsonb_build_object('accountId',u,'agreementId',a.id,
 'targetAccountId',case when u=a.requester_account_id then a.worker_account_id else a.requester_account_id end,
 'eligible',own_review is null and not private.closure_account_restricted(u) and a.status='COMPLETED' and exists(select 1 from public.agreement_execution where agreement_id=a.id and state='COMPLETED'),
 'review',own_review,'tagCatalog',jsonb_build_object('version','PRE_V3_REVIEW_TAGS_V1','maxTags',3,'tags',to_jsonb(private.review_tag_catalog())),
 'authoritative',true);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_my_agreement_review_v2(p_agreement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); a public.agreements; r private.agreement_reviews; own_review jsonb; own_comment text;
begin
 -- D12: the legacy context (same participant gate, same eligibility incl. the closure restriction, same tag catalog) plus the author's OWN comment inside the review and the comment policy.
 -- The presence of THIS function is the capability a new client tests; an older server answers PGRST202 and the client falls back to the legacy pair.
 if u is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into a from public.agreements where id=p_agreement_id and u in(requester_account_id,worker_account_id);
 if not found then raise exception 'REVIEW_NOT_ALLOWED' using errcode='42501'; end if;
 select * into r from private.agreement_reviews where agreement_id=a.id and reviewer_account_id=u;
 if found then
  select c.comment into own_comment from private.agreement_review_comments_v1 c where c.review_id=r.id;
  own_review:=private.review_receipt(r,false)||jsonb_build_object('comment',own_comment);
 end if;
 return jsonb_build_object('accountId',u,'agreementId',a.id,
 'targetAccountId',case when u=a.requester_account_id then a.worker_account_id else a.requester_account_id end,
 'eligible',own_review is null and not private.closure_account_restricted(u) and a.status='COMPLETED' and exists(select 1 from public.agreement_execution where agreement_id=a.id and state='COMPLETED'),
 'review',own_review,'tagCatalog',jsonb_build_object('version','PRE_V3_REVIEW_TAGS_V1','maxTags',3,'tags',to_jsonb(private.review_tag_catalog())),
 'commentPolicy',jsonb_build_object('supported',true,'maxLength',500,'version','REVIEW_COMMENT_V1'),
 'authoritative',true);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_public_profile(p_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_profile public.app_profiles;
  v_completed bigint := 0;
  v_reputation jsonb;
begin
  if v_actor is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  if p_profile_id is null then
    raise exception 'PROFILE_ID_REQUIRED' using errcode = '22023';
  end if;

  select p.*
  into v_profile
  from public.app_profiles p
  where p.id = p_profile_id
    and p.profile_status = 'ACTIVE'
    and p.kind in ('REQUESTER', 'WORKER');

  if not found then
    return null;
  end if;

  if private.closure_account_restricted(v_actor) or private.closure_account_restricted(v_profile.account_id) then return null; end if;
  if private.safety_pair_blocked(v_actor,v_profile.account_id) then return null; end if;
  if not private.accounts_same_world(v_actor, v_profile.account_id) then return null; end if;
  if v_profile.kind = 'REQUESTER' then
    select count(*)
    into v_completed
    from public.agreements a
    where a.requester_profile_id = v_profile.id
      and a.status = 'COMPLETED';
  else
    select count(*)
    into v_completed
    from public.agreements a
    where a.worker_profile_id = v_profile.id
      and a.status = 'COMPLETED';
  end if;

  v_reputation:=private.account_reputation(v_profile.account_id);
  return jsonb_build_object(
    'profileId', v_profile.id,
    'role', v_profile.kind,
    'displayName', nullif(btrim(v_profile.display_name), ''),
    'avatarPath', v_profile.avatar_path,
    'city', nullif(btrim(v_profile.city), ''),
    'publicSummary', jsonb_build_object(
      'headline', case when v_profile.kind = 'WORKER' then nullif(btrim(v_profile.headline), '') else null end,
      'bio', case when v_profile.kind = 'WORKER' then nullif(btrim(v_profile.bio), '') else null end
    ),
    'trust', jsonb_build_object(
      'ratingAverage', v_reputation->'averageRating',
      'reviewCount', v_reputation->'reviewCount',
      'completedCount', v_completed,
      'identityVerified', false,
      'ratingAvailable', (v_reputation->>'reviewCount')::bigint>0,
      'reviewsAvailable', true,
      'identityVerificationAvailable', false
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_list_review_comments_v1(p_profile_id uuid, p_limit integer DEFAULT 20, p_after jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_actor uuid:=auth.uid(); v_profile public.app_profiles; v_limit integer; v_after_at timestamptz; v_after_id uuid; v_items jsonb; v_more boolean;
begin
 -- D12: the gated reader of the written comments ABOUT the person whose public profile is open. One paged, account-level list (a review is account-level reputation, both roles pooled);
 -- only reviews that carry a visible comment appear (a star-only review has no text row, but the public count and average still include it, so for a small count the rating of a star-only review can be inferred by subtraction from the
 -- listed ratings: an owner-visible consequence, README_D12_CANDIDATE.md); stars, the count and the average are never changed by anything here.
 -- DESIGN DEFAULT D-DEC-7 (the owner accepted the defaults of the design): ONE account-level list usable from both profile kinds, so the same reviewIds and texts appear under the REQUESTER and the WORKER profile of one person and each item names the role
 -- of its author: an observer who has seen both faces can LINK them by comparing lists. A role-scoped list is a function-only change (add: and the target role of the Agreement equals v_profile.kind) that needs no certificate move; it is NOT implemented here.
 if v_actor is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_profile_id is null then raise exception 'PROFILE_ID_REQUIRED' using errcode='22023'; end if;
 v_limit:=least(greatest(coalesce(p_limit,20),1),50);
 if p_after is not null and jsonb_typeof(p_after)<>'null' then
  if jsonb_typeof(p_after)<>'object' or jsonb_typeof(p_after->'createdAt') is distinct from 'string' or jsonb_typeof(p_after->'reviewId') is distinct from 'string' then
   raise exception 'INVALID_PAGE' using errcode='22023';
  end if;
  begin
   v_after_at:=(p_after->>'createdAt')::timestamptz; v_after_id:=(p_after->>'reviewId')::uuid;
  exception when data_exception then raise exception 'INVALID_PAGE' using errcode='22023';
  end;
 end if;
 -- The gate stack of rpc_get_public_profile, in the same order and with the same safe failure: an ACTIVE profile only, closure-restricted viewer or subject, a blocked pair and another world all read as "nothing here".
 select p.* into v_profile from public.app_profiles p where p.id=p_profile_id and p.profile_status='ACTIVE' and p.kind in('REQUESTER','WORKER');
 if not found then return null; end if;
 if private.closure_account_restricted(v_actor) or private.closure_account_restricted(v_profile.account_id) then return null; end if;
 if private.safety_pair_blocked(v_actor,v_profile.account_id) then return null; end if;
 if not private.accounts_same_world(v_actor,v_profile.account_id) then return null; end if;
 -- Read-time gating of every row: a hidden comment, an author under a closure restriction, a pair VIEWER/author that is blocked either way (the viewer-versus-subject pair is gated above), another world, or an author profile that is not ACTIVE is not listed.
 -- DELIBERATELY NO viewer-independent block gate: a block between the author and the reviewed person must NOT remove the comment for third viewers, otherwise either party could censor or re-publish the text for everybody by toggling a block (the author edit/delete path
 -- the owner forbade, through a side door). It still hides the text from the one person who blocked its author, because that person is the VIEWER here. Hiding for everyone is the audited moderation HIDE only.
 -- KNOWN CONSEQUENCE (owner-visible, NOT decided here): the block is symmetric, so when the AUTHOR blocks the reviewed person (or blocked them before writing) that person is the viewer of a blocked pair and no longer sees the comment
 -- about them (nor its agreementId, so they cannot report it from here), is not notified, and every third viewer still sees it; the block costs the author nothing and the only remedy is the audited service-role HIDE. Options: README_D12_CANDIDATE.md.
 -- No write-time refusal exists for any of this (it would reveal a block); the author's profile is the face of the Agreement role in which the review was written. The only place an account id can appear is inside avatarPath, exactly as rpc_get_public_profile returns it.
 select coalesce(jsonb_agg(x.item order by x.created_at desc,x.review_id desc),'[]'::jsonb) into v_items from (
  select c.created_at,c.review_id,
   jsonb_build_object('reviewId',c.review_id,'rating',rv.rating,'comment',c.comment,'createdAt',c.created_at,
    'agreementId',case when v_actor=c.target_account_id then rv.agreement_id else null end,
    'author',jsonb_build_object('profileId',ap.id,'role',ap.kind,'displayName',nullif(btrim(ap.display_name),''),'avatarPath',ap.avatar_path)) as item
  from private.agreement_review_comments_v1 c
  join private.agreement_reviews rv on rv.id=c.review_id
  join public.agreements ag on ag.id=rv.agreement_id
  join public.app_profiles ap on ap.id=case when ag.requester_account_id=c.author_account_id then ag.requester_profile_id else ag.worker_profile_id end
   and ap.account_id=c.author_account_id
  where c.target_account_id=v_profile.account_id and c.hidden_at is null
   and ap.profile_status='ACTIVE' and ap.kind in('REQUESTER','WORKER')
   and not private.closure_account_restricted(c.author_account_id)
   and not private.safety_pair_blocked(v_actor,c.author_account_id)
   and private.accounts_same_world(v_actor,c.author_account_id)
   and (v_after_at is null or (c.created_at,c.review_id)<(v_after_at,v_after_id))
  order by c.created_at desc,c.review_id desc
  limit v_limit+1
 ) x;
 v_more:=jsonb_array_length(v_items)>v_limit;
 if v_more then v_items:=v_items-v_limit; end if;
 return jsonb_build_object('profileId',v_profile.id,'items',v_items,'hasMore',v_more,
  'nextAfter',case when v_more then jsonb_build_object('createdAt',v_items->(v_limit-1)->'createdAt','reviewId',v_items->(v_limit-1)->'reviewId') else null end,
  'authoritative',true);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_submit_agreement_review(p_agreement_id uuid, p_target_account_id uuid, p_rating jsonb, p_tags jsonb, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); a public.agreements; r private.agreement_reviews;
 rating_value numeric; tags_value text[]; h text; target_role text;
begin
 if u is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_agreement_id is null or p_target_account_id is null or p_target_account_id=u or p_client_request_id is null
 or jsonb_typeof(p_rating) is distinct from 'number' or length(p_rating::text)>30 then
  raise exception 'REVIEW_INPUT_INVALID' using errcode='22023';
 end if;
 rating_value:=(p_rating#>>'{}')::numeric;
 if rating_value not between 1 and 5 or trunc(rating_value)<>rating_value then
  raise exception 'REVIEW_INPUT_INVALID' using errcode='22023';
 end if;
 if jsonb_typeof(p_tags) is distinct from 'array' then raise exception 'REVIEW_TAGS_INVALID' using errcode='22023'; end if;
 if jsonb_array_length(p_tags)>3 or exists(select 1 from jsonb_array_elements(p_tags) t
  where jsonb_typeof(t.value)<>'string' or not (t.value#>>'{}'=any(private.review_tag_catalog()))) then
  raise exception 'REVIEW_TAGS_INVALID' using errcode='22023';
 end if;
 tags_value:=array(select t.value#>>'{}' from jsonb_array_elements(p_tags) t order by (t.value#>>'{}') collate "C");
 if not private.review_tags_valid(tags_value) then raise exception 'REVIEW_TAGS_INVALID' using errcode='22023'; end if;
 h:=encode(extensions.digest(jsonb_build_object('agreementId',p_agreement_id,'target',p_target_account_id,
  'rating',rating_value::integer,'tags',to_jsonb(tags_value))::text,'sha256'),'hex');
 -- Same successful command remains an immutable read, even after a later block.
 perform pg_advisory_xact_lock(hashtextextended('uskoci:review-command:'||u::text||':'||p_client_request_id::text,9120));
 select * into r from private.agreement_reviews where reviewer_account_id=u and client_request_id=p_client_request_id;
 if found then
  if r.input_hash<>h then raise exception 'REQUEST_ID_REUSED' using errcode='22023'; end if;
  return private.review_receipt(r,true);
 end if;
 select * into a from public.agreements where id=p_agreement_id and u in(requester_account_id,worker_account_id) for share;
 if not found then raise exception 'REVIEW_NOT_ALLOWED' using errcode='42501'; end if;
 if p_target_account_id<>(case when u=a.requester_account_id then a.worker_account_id else a.requester_account_id end) then
  raise exception 'REVIEW_NOT_ALLOWED' using errcode='42501';
 end if;
 if a.status<>'COMPLETED' or not exists(select 1 from public.agreement_execution where agreement_id=a.id and state='COMPLETED') then
  raise exception 'REVIEW_NOT_COMPLETED' using errcode='55000';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('uskoci:review-agreement:'||a.id::text||':'||u::text,9120));
 if exists(select 1 from private.agreement_reviews where agreement_id=a.id and reviewer_account_id=u) then
  raise exception 'REVIEW_ALREADY_SUBMITTED' using errcode='55000';
 end if;
 -- A block cannot remove the counterpart's completed-work review entitlement.
 -- P8 suppresses ordinary deliveries, including this event, for blocked pairs.
 insert into private.agreement_reviews(agreement_id,reviewer_account_id,target_account_id,rating,tags,client_request_id,input_hash)
 values(a.id,u,p_target_account_id,rating_value::integer,tags_value,p_client_request_id,h) returning * into r;
 perform private.audit_marketplace(u,'AGREEMENT_REVIEW_SUBMITTED','AGREEMENT',a.id,a.current_version,jsonb_build_object('reviewId',r.id));
 target_role:=case when u=a.requester_account_id then 'WORKER' else 'REQUESTER' end;
 perform private.emit_event(p_target_account_id,target_role,'REVIEW_RECEIVED','AGREEMENT',a.id,a.current_version,
  'Nova ocena','Dobili ste ocenu za završen Dogovor.','agreement-review:'||r.id::text,'NORMAL','{}'::jsonb,null);
 return private.review_receipt(r,false);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_submit_agreement_review_v2(p_agreement_id uuid, p_target_account_id uuid, p_rating jsonb, p_tags jsonb, p_client_request_id uuid, p_comment jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); a public.agreements; r private.agreement_reviews;
 rating_value numeric; tags_value text[]; h text; target_role text;
 comment_value text; comment_sha text; stored_comment text; stored_sha text;
begin
 -- D12: the legacy review command (same auth, validation order, locks, eligibility, star hash, audit row and REVIEW_RECEIVED event, byte for byte in behaviour) plus ONE optional comment
 -- that is stored in the SAME transaction as the stars and never later. The legacy function stays untouched and keeps serving every installed build.
 if u is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_agreement_id is null or p_target_account_id is null or p_target_account_id=u or p_client_request_id is null
 or jsonb_typeof(p_rating) is distinct from 'number' or length(p_rating::text)>30 then
  raise exception 'REVIEW_INPUT_INVALID' using errcode='22023';
 end if;
 rating_value:=(p_rating#>>'{}')::numeric;
 if rating_value not between 1 and 5 or trunc(rating_value)<>rating_value then
  raise exception 'REVIEW_INPUT_INVALID' using errcode='22023';
 end if;
 if jsonb_typeof(p_tags) is distinct from 'array' then raise exception 'REVIEW_TAGS_INVALID' using errcode='22023'; end if;
 if jsonb_array_length(p_tags)>3 or exists(select 1 from jsonb_array_elements(p_tags) t
  where jsonb_typeof(t.value)<>'string' or not (t.value#>>'{}'=any(private.review_tag_catalog()))) then
  raise exception 'REVIEW_TAGS_INVALID' using errcode='22023';
 end if;
 tags_value:=array(select t.value#>>'{}' from jsonb_array_elements(p_tags) t order by (t.value#>>'{}') collate "C");
 if not private.review_tags_valid(tags_value) then raise exception 'REVIEW_TAGS_INVALID' using errcode='22023'; end if;
 -- The star hash keeps the legacy formula exactly (so every stored hash and every replay through either function stays compatible); the comment is bound by its own digest in its own row.
 h:=encode(extensions.digest(jsonb_build_object('agreementId',p_agreement_id,'target',p_target_account_id,
  'rating',rating_value::integer,'tags',to_jsonb(tags_value))::text,'sha256'),'hex');
 comment_value:=private.review_comment_input_v1(p_comment);
 comment_sha:=case when comment_value is null then null else encode(extensions.digest(convert_to(comment_value,'UTF8'),'sha256'),'hex') end;
 -- Same successful command remains an immutable read, even after a later block.
 perform pg_advisory_xact_lock(hashtextextended('uskoci:review-command:'||u::text||':'||p_client_request_id::text,9120));
 select * into r from private.agreement_reviews where reviewer_account_id=u and client_request_id=p_client_request_id;
 if found then
  if r.input_hash<>h then raise exception 'REQUEST_ID_REUSED' using errcode='22023'; end if;
  -- A comment that differs from the stored one (or one added to a stored star-only review) is another command under the same id.
  select c.comment,c.comment_sha256 into stored_comment,stored_sha from private.agreement_review_comments_v1 c where c.review_id=r.id;
  if stored_sha is distinct from comment_sha then raise exception 'REQUEST_ID_REUSED' using errcode='22023'; end if;
  return private.review_receipt(r,true)||jsonb_build_object('comment',stored_comment);
 end if;
 select * into a from public.agreements where id=p_agreement_id and u in(requester_account_id,worker_account_id) for share;
 if not found then raise exception 'REVIEW_NOT_ALLOWED' using errcode='42501'; end if;
 if p_target_account_id<>(case when u=a.requester_account_id then a.worker_account_id else a.requester_account_id end) then
  raise exception 'REVIEW_NOT_ALLOWED' using errcode='42501';
 end if;
 if a.status<>'COMPLETED' or not exists(select 1 from public.agreement_execution where agreement_id=a.id and state='COMPLETED') then
  raise exception 'REVIEW_NOT_COMPLETED' using errcode='55000';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('uskoci:review-agreement:'||a.id::text||':'||u::text,9120));
 if exists(select 1 from private.agreement_reviews where agreement_id=a.id and reviewer_account_id=u) then
  raise exception 'REVIEW_ALREADY_SUBMITTED' using errcode='55000';
 end if;
 -- A block cannot remove the counterpart's completed-work review entitlement (stars and comment alike; a refusal would reveal the block).
 -- P8 suppresses ordinary deliveries, including this event, for blocked pairs. The comment is hidden from readers while the pair is blocked, at read time.
 insert into private.agreement_reviews(agreement_id,reviewer_account_id,target_account_id,rating,tags,client_request_id,input_hash)
 values(a.id,u,p_target_account_id,rating_value::integer,tags_value,p_client_request_id,h) returning * into r;
 if comment_value is not null then
  insert into private.agreement_review_comments_v1(review_id,author_account_id,target_account_id,comment,comment_sha256,created_at)
  values(r.id,r.reviewer_account_id,r.target_account_id,comment_value,comment_sha,r.created_at);
 end if;
 perform private.audit_marketplace(u,'AGREEMENT_REVIEW_SUBMITTED','AGREEMENT',a.id,a.current_version,jsonb_build_object('reviewId',r.id));
 target_role:=case when u=a.requester_account_id then 'WORKER' else 'REQUESTER' end;
 perform private.emit_event(p_target_account_id,target_role,'REVIEW_RECEIVED','AGREEMENT',a.id,a.current_version,
  'Nova ocena','Dobili ste ocenu za zavr'||chr(353)||'en Dogovor.','agreement-review:'||r.id::text,'NORMAL','{}'::jsonb,null);
 return private.review_receipt(r,false)||jsonb_build_object('comment',comment_value);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_tick_auto_completion()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare candidate record; a public.agreements; x public.agreement_execution; done integer:=0; at_time timestamptz:=statement_timestamp();
begin
 for candidate in select ag.id,ag.need_id from public.agreements ag join public.agreement_execution ex on ex.agreement_id=ag.id
   where ag.status='CONFIRMED' and ex.state='AWAITING_REQUESTER' and ex.problem_opened_at is null
     and ex.requester_deadline_at is not null and ex.requester_deadline_at<=at_time
   order by ag.need_id,ag.id limit 100
 loop
   perform 1 from public.needs where id=candidate.need_id for update skip locked;
   if not found then continue; end if;
   select * into a from public.agreements where id=candidate.id for update skip locked;
   if not found or a.status<>'CONFIRMED' then continue; end if;
   select * into x from public.agreement_execution where agreement_id=a.id for update skip locked;
   if not found or x.state<>'AWAITING_REQUESTER' or x.agreement_version<>a.current_version
     or x.problem_opened_at is not null or x.requester_deadline_at is null or x.requester_deadline_at>at_time
     or exists(select 1 from public.agreement_change_proposals where agreement_id=a.id and status='PENDING') then continue; end if;
   update public.agreement_execution set state='COMPLETED',completed_at=at_time,requester_deadline_at=null,updated_at=at_time where agreement_id=a.id;
   update public.agreements set status='COMPLETED',updated_at=at_time where id=a.id;
   perform private.sync_need_completion(a.need_id);
   -- PKG-029a (deep read 1.2): the worker is told the job closed, exactly as when the requester confirms (same
   -- event, same dedupe key, so the two paths can never both notify).
   perform private.emit_event(a.worker_account_id, 'WORKER', 'EXECUTION_STATE_CHANGED', 'AGREEMENT', a.id, a.current_version,
     'Dogovor je završen', 'Rok za potvrdu je istekao, pa je završetak potvrđen automatski.',
     'completed:worker:' || a.id::text || ':' || a.current_version::text, 'NORMAL',
     jsonb_build_object('completedAt', at_time, 'automatic', true), null);
   done:=done+1;
 end loop;
 return done;
end;
$function$

CREATE OR REPLACE FUNCTION public.selectable_application_count(n needs)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare actor uuid:=auth.uid(); actual public.needs; result integer;
begin
  if actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if not public.rpc_storage_account_open() then raise exception 'ACCOUNT_NOT_OPEN' using errcode='42501'; end if;
  -- Only the ID is input. Never trust owner/status/price fields in a caller-supplied composite.
  select * into actual from public.needs t where t.id=n.id and t.requester_account_id=actor;
  if not found then return null; end if;
  select count(*)::integer into result from private.need_candidate_states_v5(actual.id) c
    where c.candidate_state='SELECTABLE';
  return result;
end;
$function$
